import{_ as t,b as l,c as o,g as n}from"./chunks/framework.86O3EbG5.js";const _=JSON.parse('{"title":"不确定性的量化","description":"","frontmatter":{"title":"不确定性的量化","subTitle":"《人工智能现代方法》读书笔记","author":"oasis","date":"2023-04-04T00:00:00.000Z","tags":["AI"]},"headers":[],"relativePath":"articles/artificial-intelligence/books/AI-modern-approach/12.md","filePath":"articles/artificial-intelligence/books/AI-modern-approach/12.md"}'),r={name:"articles/artificial-intelligence/books/AI-modern-approach/12.md"};function s(e,i,a,g,c,d){return l(),o("div",null,[...i[0]||(i[0]=[n('<p>第 12 章从一阶逻辑的表示能力出发，探讨了现实中如何组织和构建知识库，重点在于本体（Ontology）的设计。核心内容包括：</p><h2 id="本体工程" tabindex="-1">本体工程</h2><ul><li><strong>本体</strong>：描述世界中存在的事物类型、属性、关系</li><li><strong>顶层本体</strong>：包括时间、空间、物质、事件、心智等通用概念</li><li><strong>分类学（Taxonomy）</strong>：is-a 层次结构（如 动物 → 哺乳动物 → 人类）</li><li><strong>组合与部分关系</strong>：part-of（如 翅膀是鸟的一部分），以及不同种类的组合（如聚集、构成）</li></ul><h2 id="继承与默认推理" tabindex="-1">继承与默认推理</h2><ul><li><strong>属性继承</strong>：子类自动继承父类的属性</li><li><strong>默认值</strong>（如 鸟通常能飞），需要处理例外（如鸵鸟不能飞）</li><li><strong>非单调逻辑</strong>：新信息可撤销旧结论（如得知企鹅是鸟，撤销「鸟能飞」）</li></ul><h2 id="表示复杂性" tabindex="-1">表示复杂性</h2><ul><li><strong>描述逻辑（Description Logic）</strong>：一阶逻辑的可判定子集，用于本体语言（如 OWL）</li><li>概念、角色、个体，以及构造子（交集、并集、存在量词限制等）</li><li>推理任务：包含（subsumption）、实例检验（instance checking）</li></ul><h2 id="具体领域本体" tabindex="-1">具体领域本体</h2><ul><li><strong>物质</strong>：物质与物体、量度、质量、容积等</li><li><strong>空间</strong>：位置、形状、拓扑关系（相接、包含、分离）</li><li><strong>时间</strong>：时间点、区间、时序关系（前、后、同时）</li><li><strong>心智</strong>：信念、意图、目标（用于多智能体）</li><li><strong>事件</strong>：过程、因果、参与者（如《事件演算》）</li></ul><h2 id="表示与推理系统的实现" tabindex="-1">表示与推理系统的实现</h2><ul><li>语义网、RDF、OWL 简介</li><li>知识库的调试、一致性和冗余检测</li></ul><p>本章强调：知识表示不是单纯编码，而是需要精心的本体设计，平衡表达力与可计算性。</p>',12)])])}const u=t(r,[["render",s]]);export{_ as __pageData,u as default};
